{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01VEzbcRn9t7wSvzHWhTb91U","type":"tool_result","content":"1\t\"\"\"Preregistered honest-successor visibility and welfare study.\"\"\"\n2\t\n3\tfrom __future__ import annotations\n4\t\n5\timport argparse\n6\timport json\n7\tfrom pathlib import Path\n8\timport random\n9\timport secrets\n10\timport subprocess\n11\tfrom typing import Any\n12\t\n13\tfrom dogwhistle.allocation import VENDORS, benchmark, generate_instances, score\n14\tfrom dogwhistle.gate import handoff, public_refs\n15\tfrom dogwhistle.heldout import codeword\n16\tfrom dogwhistle.stats import sign_flip_one_sided\n17\tfrom dogwhistle.study import checkpoint, digest, ensure_published, invoke, label_commitment, load, write\n18\tfrom dogwhistle.visibility import eligible_targets\n19\tfrom prior_work.nns_snapshot.src.neural_node_swarm.verifier import verify_node_output\n20\t\n21\t\n22\tROOT = Path(__file__).resolve().parents[1]\n23\tFOLDER = ROOT / \"honest\"\n24\tREGISTRATION = FOLDER / \"registration.json\"\n25\tSECRET = FOLDER / \".private\" / \"labels.json\"\n26\tSEED = 20261027\n27\tINSTANCES = 30\n28\tREPLICATES = 3\n29\tARMS = (\"codeword\", \"public\")\n30\tTRIALS = INSTANCES * REPLICATES * len(ARMS)\n31\tBOOTSTRAPS = 10_000\n32\tBOOTSTRAP_SEED = 72541\n33\tSOURCE_FILES = (\n34\t    \"honest/PROTOCOL.md\", \"honest/registration.json\",\n35\t    \"dogwhistle/honest.py\", \"dogwhistle/honest_adapter.py\", \"tests/test_honest.py\",\n36\t    \"dogwhistle/assignment.schema.json\", \"dogwhistle/codex_adapter.py\",\n37\t    \"dogwhistle/allocation.py\", \"dogwhistle/gate.py\", \"dogwhistle/heldout.py\",\n38\t    \"dogwhistle/visibility.py\", \"dogwhistle/stats.py\", \"dogwhistle/study.py\",\n39\t    \"prior_work/nns_snapshot/schemas/node_output.schema.json\",\n40\t    \"prior_work/nns_snapshot/src/neural_node_swarm/verifier.py\", \"pyproject.toml\",\n41\t)\n42\t\n43\t\n44\tdef trial_input(task: dict, pair: tuple[str, str], arm: str) -> d